/** Everything a user can choose about the look (mirrors desktop's `ThemeSpec`). Presets only. */
data class ThemeSpec(
    val accent: AccentPreset = AccentPreset.SageTeal,
    val background: BackgroundPreset = BackgroundPreset.Warm,
    val appearance: AppearanceChoice = AppearanceChoice.System,
    val tint: Boolean = false,
    val contrast: ContrastLevel = ContrastLevel.Standard,
    val density: Density = Density.Comfortable,
    val textSize: TextSize = TextSize.P100,
) {
    /** Index among the 320 looks (appearance only decides `dark`), as desktop's `look_index`. */
    internal fun lookIndex(dark: Boolean): Int {
        var i = accent.ordinal
        i = i * 5 + background.ordinal
        i = i * 2 + (if (dark) 1 else 0)
        i = i * 2 + (if (tint) 1 else 0)
        return i * 2 + (if (contrast == ContrastLevel.High) 1 else 0)
    }
}

