/** A spring in SwiftUI's terms (perceptual duration, bounce); desktop's `motion_*` tokens. */
data class SpringToken(val duration: Float, val bounce: Float) {
    /** Compose spring: omega = 2 pi / duration, stiffness = omega^2, damping ratio = 1 - bounce. */
    fun <T> spec(visibilityThreshold: T? = null): SpringSpec<T> {
        val omega = (2 * PI / duration).toFloat()
        val zeta = if (bounce >= 0f) 1f - bounce else 1f / (1f + bounce)
        return SpringSpec(dampingRatio = zeta, stiffness = omega * omega, visibilityThreshold = visibilityThreshold)
    }
}

object Motion {
    val control = SpringToken(0.2f, 0f)
    val disclosure = SpringToken(0.3f, 0f)
    val overlay = SpringToken(0.24f, 0f)
    val pop = SpringToken(0.25f, 0.15f)
    val press = SpringToken(0.1f, 0f)
    val reflow = SpringToken(0.4f, 0f)
}

data class ShadowLayer(val x: Dp, val y: Dp, val blur: Dp, val color: Color)

object Elevation {
    /** Menus, popovers, tooltips. Prefer the platform's own elevation on sheets and menus. */
    fun popover(dark: Boolean): List<ShadowLayer> = if (dark) popoverDark else popoverLight
    fun modal(dark: Boolean): List<ShadowLayer> = if (dark) modalDark else modalLight
    private val popoverDark = listOf(ShadowLayer(0.dp, 1.dp, 2.dp, rgba(0x0401004D)), ShadowLayer(0.dp, 6.dp, 16.dp, rgba(0x04010061)))
    private val popoverLight = listOf(ShadowLayer(0.dp, 1.dp, 2.dp, rgba(0x04010020)), ShadowLayer(0.dp, 6.dp, 16.dp, rgba(0x04010029)))
    private val modalDark = listOf(ShadowLayer(0.dp, 2.dp, 6.dp, rgba(0x0401004D)), ShadowLayer(0.dp, 16.dp, 40.dp, rgba(0x04010080)))
    private val modalLight = listOf(ShadowLayer(0.dp, 2.dp, 6.dp, rgba(0x04010020)), ShadowLayer(0.dp, 16.dp, 40.dp, rgba(0x04010036)))
}

// region Avatars

object AvatarStyle {
    /** Ink on every avatar fill. */
    val ink: Color = rgba(0xFDFAF6FF)
    /** Which of the 8 fills `id` gets: FNV-1a over the UTF-8 bytes, so it matches desktop. */
    fun fillIndex(id: String): Int {
        var h = 0x811c9dc5L
        for (b in id.encodeToByteArray()) {
            h = h xor (b.toLong() and 0xFF)
            h = (h * 0x01000193L) and 0xFFFFFFFFL
        }
        return (h % 8).toInt()
    }
    fun fill(id: String, accent: AccentPreset): Color = accent.avatarFills()[fillIndex(id)]
    /** Up to two initials: the first letters of the first two words. */
    fun initials(name: String): String =
        name.split(Regex("\\s+")).filter { it.isNotEmpty() }.take(2).joinToString("") { it.first().uppercase() }
}

// region Theme

/** A `ThemeSpec` resolved for the system appearance: colours, metrics and type, ready to read. */
class Theme(val spec: ThemeSpec = ThemeSpec(), systemDark: Boolean = true) {
    val isDark: Boolean = spec.appearance.isDark(systemDark)
    val colors: ThemeColors = ThemeColors.unpack(DesignLooks.all[spec.lookIndex(isDark)])
    val metrics: Metrics = Metrics.of(spec.density, spec.textSize)
    val type: TypeRamp get() = metrics.type
    val colorScheme: ColorScheme get() = colors.toColorScheme(isDark)

    override fun equals(other: Any?) = other is Theme && other.spec == spec && other.isDark == isDark
    override fun hashCode() = 31 * spec.hashCode() + isDark.hashCode()
}

val LocalTheme = staticCompositionLocalOf { Theme() }

